inputs.assembly.nix:
let
  owner = builtins.getFlake "path:/home/brittonr/git/OnixResearch/onixos";
  kiln = builtins.getFlake "path:/home/brittonr/git/OnixResearch/kiln";
  outputs = owner.lib.x86_64-linux.mkFlake {
    inputs.nixpkgs = kiln.inputs.nixpkgs;
    inputs.preservation = builtins.getFlake "github:nix-community/preservation/00be7f7dd1a11ae0605386f2272288de7cf33abe";
    inventoryFile = ./inventory.ncl;
    modules = {};
    moduleInputs.kiln = kiln.onixModules;
    overlays = [ (final: prev: { kiln-web-service = kiln.packages.${final.stdenv.hostPlatform.system}.web-service; }) ];
    extraNixosModules.qualification = [ {
      boot.loader.grub.devices = ["nodev"];
      fileSystems."/" = { device = "none"; fsType = "tmpfs"; };
      fileSystems."/persist" = { device = "/dev/disk/by-label/qualification-persist"; fsType = "ext4"; neededForBoot = true; };
      system.stateVersion = "26.05";
    } ];
  };
  system = outputs.nixosConfigurations.qualification;
in {
  unit = system.config.systemd.units."kiln-web-service.service".text;
  account = system.config.users.users.kiln-web-service.uid;
  system_derivation = system.config.system.build.toplevel.drvPath;
}

inputs.inventory.ncl:
let onix = import "/home/brittonr/git/OnixResearch/onixos/lib/onix.ncl" in
{
  machines | {_ : onix.Machine} | onix.NameMatchesKey = {
    qualification = {
      name = "qualification",
      system = "x86_64-linux",
      class = 'nixos,
      tags = ["isolated-evaluation"],
      deploy.targetHost = "root@qualification.invalid",
      preservation = { enable = true, persistentStoragePath = "/persist" },
    },
  },
  instances | {_ : onix.Instance} = {
    web = {
      service = "kiln-web-service",
      module = { input = "kiln", name = "kiln-web-service" },
      roles.server = {
        machines = ["qualification"],
        settings = (import "/home/brittonr/git/OnixResearch/kiln/deployment/fixtures/inputs.ncl") & { uid = 41001, gid = 41001 },
      },
    },
  },
}
